import React from 'react';
import { MenuItem } from '@fiverr-private/dropdown';
import { useInputTrackValue } from '@fiverr-private/inputs';
import { OptionProps } from './types';

const Option = ({ value, disabled, children, dataTrackTag = 'select_option', dataTrackValue }: OptionProps) => {
  const trackValue = useInputTrackValue({ dataTrackValue, value });
  return (
    <MenuItem dataTrackTag={dataTrackTag} dataTrackValue={trackValue} value={value} disabled={disabled} selectable>
      {children}
    </MenuItem>
  );
};

Option.displayName = 'Option';

export default Option;
