import { countries } from '../../Combobox/stories/utils';

const REQUIRED_ERROR = 'This field is required';

export const PrimaryStory = (args: Omit<FormProps<FieldValues>, 'methods'>) => {
  const schema = z4.object({
    name: z4.string().min(2, { message: 'name must contain at least 2 character(s)' }),
  });

  type SchemaType = z4.infer<typeof schema>;

  const onSubmit: SubmitHandler<SchemaType> = (data) => {
    alert(JSON.stringify(data));
  };
  const methods = useForm<SchemaType>({
    resolver: standardSchemaResolver(schema),
  });
  return (
    <Form methods={methods} {...args} onSubmit={onSubmit}>
      <FormControl maxLength={6} name="name">
        <FormHeader>
          <FormLabel>Label</FormLabel>
          <FormTooltip content="Accusantium minima ad a dignissimos commodi facilis et tempore." />
          <FormSubtitle>FormSubtitle</FormSubtitle>
        </FormHeader>
        <FormElement>
          <Input placeholder="name" />
        </FormElement>
        <FormHelperText hint="This is a hint" success="Success message" error="Error message" />
        <FormCounter />
      </FormControl>
      <Button type="submit">Submit</Button>
    </Form>
  );
};

export const ControlledStory = () => {
  const schema = z4.object({
    name: z4.string().min(2, { message: 'name must contain at least 2 character(s)' }),
    description: z4.string().min(20, { message: 'description must contain at least 20 character(s)' }),
    switch: z4.literal<boolean>(true, { error: REQUIRED_ERROR }),
    radio: z4.string({
      error: REQUIRED_ERROR,
    }),
    checkbox: z4
      .string({
        error: REQUIRED_ERROR,
      })
      .array()
      .length(2, { message: 'Select actually two items' }),
    choiceGroup: z4.array(z4.string(), { error: REQUIRED_ERROR }).nonempty(),
    inputGroup: z4.string().min(2, { message: 'name must contain at least 2 character(s)' }),
    select: z4.object(
      {
        item: z4.string(),
      },
      { error: REQUIRED_ERROR }
    ),
    combobox: z4.object(
      {
        item: z4.string(),
      },
      { error: REQUIRED_ERROR }
    ),
  });

  type SchemaType = z4.infer<typeof schema>;

  const methods = useForm<SchemaType>({
    resolver: standardSchemaResolver(schema),
  });
  const onSubmit: SubmitHandler<SchemaType> = (data) => {
    alert(JSON.stringify(data));
  };
  const [input, setInput] = useState('');
  const [textarea, setTextarea] = useState('');
  const [checkboxGroup, setCheckboxGroup] = useState<string[]>([]);
  const [switchValue, setSwitchValue] = useState(false);
  const [inputGroup, setInputGroup] = useState('');
  const selectDefault = ['pie', 'souffle', 'cheesecake'];
  const [selectOptions] = useState(selectDefault);
  const [radio, setRadio] = useState('');
  const choiceGroupData = ['Lorem, ipsum dolor 1', 'Lorem, ipsum dolor 2', 'Lorem, ipsum dolor 3'];

  return (
    <Form methods={methods} onSubmit={onSubmit}>
      <FormControl name="name" maxLength={6}>
        <FormHeader>
          <FormLabel>Input</FormLabel>
          <FormTooltip content="Accusantium minima ad a dignissimos commodi facilis et tempore." />
          <FormSubtitle>FormSubtitle</FormSubtitle>
        </FormHeader>
        <FormElement>
          <Input placeholder="name" value={input} onChange={(e) => setInput(e.target.value)} />
        </FormElement>
        <FormHelperText
          hint={
            <>
              This is a <Typography as="strong">hint</Typography>
            </>
          }
          error={
            <>
              This is an <Typography as="strong">error</Typography>
            </>
          }
        />
      </FormControl>
      <FormControl name="description" maxLength={40}>
        <FormHeader>
          <FormLabel>Textarea</FormLabel>
          <FormSubtitle>FormSubtitle</FormSubtitle>
        </FormHeader>
        <FormElement>
          <Textarea value={textarea} onChange={(e) => setTextarea(e.target.value)} placeholder="description" />
        </FormElement>
        <FormCounter />
        <FormHelperText hint="Select the project that best fits your needs Select the project that best fits your needs Select the project that best fits your needs" />
      </FormControl>
      <FormControl name="checkbox">
        <FormHeader>
          <FormLabel>CheckboxGroup</FormLabel>
          <FormTooltip content="Accusantium minima ad a dignissimos commodi facilis et tempore." />
        </FormHeader>
        <FormElement>
          <CheckboxGroup value={checkboxGroup} onChange={setCheckboxGroup}>
            <Checkbox value="checkbox1">Check me out 1!</Checkbox>
            <Checkbox value="checkbox2">Check me out 2!</Checkbox>
            <Checkbox value="checkbox3">Check me out 3!</Checkbox>
          </CheckboxGroup>
        </FormElement>
        <FormHelperText hint="This is a hint" />
      </FormControl>
      <FormControl name="switch">
        <FormHeader>
          <FormLabel>Switch</FormLabel>
          <FormTooltip content="Accusantium minima ad a dignissimos commodi facilis et tempore." />
          <FormSubtitle>FormSubtitle</FormSubtitle>
        </FormHeader>
        <FormElement>
          <Switch defaultChecked={switchValue} onChange={(value) => setSwitchValue(!value)} size="sm">
            Switch me
          </Switch>
        </FormElement>
        <FormHelperText hint="This is a hint" />
      </FormControl>
      <FormControl name="choiceGroup">
        <FormHeader>
          <FormLabel>ChoiceGroup</FormLabel>
          <FormTooltip content="Accusantium minima ad a dignissimos commodi facilis et tempore." />
          <FormSubtitle>FormSubtitle - ChoiceGroup</FormSubtitle>
        </FormHeader>
        <FormElementController
          render={({ field: { onChange, value = [], ref } }) => (
            <ChoiceGroup
              multiple
              value={value}
              onChange={(newValue) => {
                onChange(newValue);
              }}
              ref={ref}
            >
              {choiceGroupData.map((item) => (
                <ChoiceGroupItem value={item} key={item}>
                  Value: {item}
                </ChoiceGroupItem>
              ))}
            </ChoiceGroup>
          )}
        />
        <FormHelperText hint="This is a hint" />
      </FormControl>
      <FormControl name="inputGroup">
        <FormHeader>
          <FormLabel>InputGroup</FormLabel>
          <FormTooltip content="Accusantium minima ad a dignissimos commodi facilis et tempore." />
          <FormSubtitle>FormSubtitle</FormSubtitle>
        </FormHeader>
        <FormElement>
          <InputGroup value={inputGroup} onChange={(e) => setInputGroup(e.target.value)}>
            <Input placeholder="inputGroup" />
          </InputGroup>
        </FormElement>
        <FormHelperText hint="This is a hint" />
      </FormControl>
      <FormControl name="radio">
        <FormHeader>
          <FormLabel>RadioGroup</FormLabel>
          <FormTooltip content="Accusantium minima ad a dignissimos commodi facilis et tempore." />
          <FormSubtitle>FormSubtitle</FormSubtitle>
        </FormHeader>
        <FormElement>
          <RadioGroup value={radio} onChange={setRadio}>
            <Radio value="radio1">Radio 1</Radio>
            <Radio value="radio2">Radio 2</Radio>
          </RadioGroup>
        </FormElement>
        <FormHelperText hint="This is a hint" />
      </FormControl>
      <FormControl name="select">
        <FormHeader>
          <FormLabel>Select</FormLabel>
          <FormTooltip content="Accusantium minima ad a dignissimos commodi facilis et tempore." />
          <FormSubtitle>FormSubtitle</FormSubtitle>
        </FormHeader>
        <FormElementController
          render={({ field: { onChange, value, ref } }) => (
            <Select
              fullWidth
              size="lg"
              placeholder="Select a pastry"
              onChange={(value) => {
                onChange(value);
              }}
              value={value}
              ref={ref}
            >
              {selectOptions.map((option) => (
                <Option key={option} value={option}>
                  {option}
                </Option>
              ))}
            </Select>
          )}
        />
        <FormHelperText hint="This is a hint" />
      </FormControl>
      <FormControl name="combobox">
        <FormHeader>
          <FormLabel>Combobox</FormLabel>
          <FormTooltip content="Accusantium minima ad a dignissimos commodi facilis et tempore." />
          <FormSubtitle>FormSubtitle</FormSubtitle>
        </FormHeader>
        <FormElementController
          render={({ field: { onChange, value, ref } }) => (
            <Combobox placeholder="Select a country" onChange={(value) => onChange(value)} value={value} ref={ref}>
              {countries.map(({ name, value }) => (
                <ComboboxOption key={value} value={value}>
                  <ComboboxOptionLabel>{name}</ComboboxOptionLabel>
                </ComboboxOption>
              ))}
            </Combobox>
          )}
        />
        <FormHelperText hint="This is a hint" />
      </FormControl>
      <Button type="submit">Submit</Button>
    </Form>
  );
};

