export const DynamicFieldsStory = () => {
  const schema = z4.object({
    select: z4
      .object(
        {
          item: z4.string().min(1),
        },
        { error: 'This field is required' }
      )
      .strict(),
    select1: z4.object(
      {
        item: z4.string().min(1),
      },
      { error: 'This field is required' }
    ),
  });

  type SchemaType = z4.infer<typeof schema>;

  const methods = useForm<SchemaType>({
    resolver: standardSchemaResolver(schema),
  });

  const onSubmit: SubmitHandler<FieldValues> = (data) => {
    alert(JSON.stringify(data));
  };

  const selectDefault = ['pie', 'souffle', 'cheesecake'];

  const optionsMapper = {
    pie: ['pie', 'pie1'],
    souffle: ['souffle', 'souffle1'],
    cheesecake: ['cheesecake', 'cheesecake1'],
  };
  return (
    <Form methods={methods} onSubmit={onSubmit}>
      <FormControl name="select">
        <FormHeader>
          <FormLabel>Label</FormLabel>
          <FormTooltip content="Accusantium minima ad a dignissimos commodi facilis et tempore." />
          <FormSubtitle>FormSubtitle</FormSubtitle>
        </FormHeader>
        <FormElementController
          render={({ field: { onChange, value } }) => (
            <Select
              placeholder="Select 1"
              value={value}
              onChange={(value) => {
                onChange(value);
                methods.setValue('select1.item', '');
              }}
            >
              {selectDefault.map((option) => (
                <Option key={option} value={option}>
                  {option}
                </Option>
              ))}
            </Select>
          )}
        />
        <FormHelperText hint="This is a hint" />
      </FormControl>
      <FormControl name="select1">
        <FormHeader>
          <FormLabel>Label</FormLabel>
          <FormTooltip content="Accusantium minima ad a dignissimos commodi facilis et tempore." />
          <FormSubtitle>FormSubtitle</FormSubtitle>
        </FormHeader>
        <FormElementController
          render={({ field: { onChange, value } }) => {
            const { item } = methods.watch('select') || {};
            const options = optionsMapper?.[item];

            return (
              <Select disabled={!options?.length} placeholder="Select 2" value={value} onChange={onChange}>
                {options &&
                  options.map((option) => (
                    <Option key={option} value={option}>
                      {option}
                    </Option>
                  ))}
              </Select>
            );
          }}
        />
        <FormHelperText hint="This is a hint" />
      </FormControl>
      <Button type="submit">Submit</Button>
    </Form>
  );
};

