import React, { useState, useCallback, useMemo, type ReactElement, useEffect, forwardRef } from 'react';
import { isNil, isUndefined } from 'lodash';
import {
  Dropdown,
  DropdownAnchor,
  DropdownContent,
  DropdownMenu,
  type Values,
  getIsMultiSelect,
} from '@fiverr-private/dropdown';
import { getContext } from '@fiverr-private/fiverr_context';
import { useInputTrackValue } from '@fiverr-private/inputs';
import type { SelectProps } from './types';
import type { OptionProps } from './Option/types';
import { SELECT_NAME, SELECT_SIZES } from './constants';
import Trigger from './Trigger';

const Select = forwardRef<HTMLDivElement, SelectProps>(
  (
    {
      disabled,
      children,
      values,
      defaultValues,
      name = SELECT_NAME,
      onChange,
      placeholder,
      isSuccess,
      isError,
      hideChevron = false,
      size = SELECT_SIZES.default,
      isOpen,
      onOpenChanged,
      initialOpen,
      disableFlip,
      position,
      fullWidth,
      onTriggerFocus,
      autoFocus,
      onTriggerBlur,
      copies,
      defaultValue: defaultValueProp,
      value: valueProp,
      width,
      selectedItemRenderer,
      selectedIndicatorPosition,
      appendToBody,
      goExperimental = false,
      theme = 'light',
      dataTrackTag = 'select',
      dataTrackValue,
    },
    ref
  ) => {
    const value = isUndefined(values) ? valueProp : values;
    const defaultValue = isUndefined(defaultValues) ? defaultValueProp : defaultValues;
    const controlled = !isUndefined(value);
    const options = useMemo(() => React.Children.toArray(children), [children]) as ReactElement<OptionProps>[];
    const [selectedValues, setSelectedValues] = useState<Values>(value || (defaultValue as Values));
    const trackValue = useInputTrackValue({ dataTrackValue, value: selectedValues });
    const { isMobile } = getContext();
    const isFullWidth = !isNil(fullWidth) ? fullWidth : isMobile;
    const isMultiSelect = getIsMultiSelect(children);
    const currentTheme = goExperimental ? 'dark' : theme;

    useEffect(() => {
      if (controlled) {
        setSelectedValues(value || {});
      }
    }, [controlled, value]);

    const handleChange = useCallback(
      (newValues: Values) => {
        if (controlled) {
          onChange?.(newValues);
          return;
        }

        setSelectedValues(newValues);
        onChange?.(newValues);
      },
      [onChange, controlled]
    );

    return (
      <Dropdown
        defaultValues={defaultValue}
        values={value}
        onChange={handleChange}
        searchWhenClosed={true}
        position={position}
        isOpen={isOpen}
        onOpenChanged={onOpenChanged}
        initialOpen={initialOpen}
        disableFlip={disableFlip}
        selectedIndicatorPosition={selectedIndicatorPosition}
        theme={currentTheme}
      >
        <DropdownAnchor
          fullWidth={isFullWidth}
          disabled={disabled}
          onFocus={onTriggerFocus}
          onBlur={onTriggerBlur}
          ref={ref}
          embed
        >
          <Trigger
            isMultiSelect={isMultiSelect}
            width={width}
            placeholder={placeholder}
            name={name}
            isSuccess={isSuccess}
            isError={isError}
            disabled={disabled}
            size={size}
            hideChevron={hideChevron}
            fullWidth={isFullWidth}
            controlled={controlled}
            options={options}
            selectedValues={selectedValues}
            copies={copies}
            onChange={onChange}
            selectedItemRenderer={selectedItemRenderer}
            autoFocus={autoFocus}
            theme={currentTheme}
            dataTrackTag={dataTrackTag}
            dataTrackValue={trackValue}
          />
        </DropdownAnchor>
        <DropdownContent fullWidth={fullWidth} appendToBody={appendToBody}>
          <DropdownMenu>{children}</DropdownMenu>
        </DropdownContent>
      </Dropdown>
    );
  }
);

Select.displayName = 'Select';

export default Select;
