import { type ReactElement, useMemo } from 'react';
import { isEmpty, isUndefined, omitBy } from 'lodash';
import type { ItemValue, Values } from '@fiverr-private/dropdown';
import { childrenIdMatch } from '@fiverr-private/ui_utils';
import type { OptionProps } from '../Option/types';
import type { SelectTriggerProps } from '../Trigger/types';
import type { SelectProps } from '../types';

const getSelectedOption = (options: SelectTriggerProps['options'], groupValue: ItemValue | ItemValue[]) => {
    const isGroup = options.length ? childrenIdMatch(options[0], 'MenuGroup') : false;
    if (isGroup) {
        let selectedOption: ReactElement<OptionProps> | undefined;
        options.forEach((option) => {
            if (option.props.children && !selectedOption) {
                selectedOption = (option.props.children as ReactElement<OptionProps>[])?.find(
                    (item) => item.props.value === groupValue
                );
            }
        });
        return selectedOption;
    }
    return options.find((option) => option?.props.value === groupValue);
};

const getSelectedLabelContent = (
    selectedValues: Values,
    options: SelectTriggerProps['options'],
    isMultiSelect: boolean | null,
    copies: SelectTriggerProps['copies'],
    selectedItemRenderer: SelectTriggerProps['selectedItemRenderer']
) => {
    const groupsValues = Object.values(selectedValues);
    const flatGroupsValues = Object.values(groupsValues).flatMap((value) => value);
    if (isEmpty(flatGroupsValues)) {
        return;
    }

    if (isMultiSelect) {
        return copies?.itemsSelectedText(flatGroupsValues.length);
    } else {
        const selectedOption = getSelectedOption(options, groupsValues[0]);
        if (!selectedOption) {
            return null;
        }
        return selectedItemRenderer ? selectedItemRenderer(selectedOption) : selectedOption.props.children;
    }
};

export const useSelectedLabelContent = (
    selectedValues: Values,
    options: ReactElement<OptionProps>[],
    copies: SelectProps['copies'],
    selectedItemRenderer: SelectProps['selectedItemRenderer'],
    isMultiSelect: boolean
) => {
    const selectLabelContent = useMemo(() => {
        if (!isEmpty(omitBy(selectedValues, isUndefined))) {
            return getSelectedLabelContent(selectedValues, options, isMultiSelect, copies, selectedItemRenderer);
        }

        return null;
    }, [copies, isMultiSelect, options, selectedItemRenderer, selectedValues]);

    return selectLabelContent;
};
