import React from 'react';
import { MenuGroup } from '@fiverr-private/dropdown';
import { OptionGroupProps } from './types';

const OptionGroup = ({
  children,
  label = '',
  isMulti = false,
  name,
  dataTrackTag = 'option_group',
  dataTrackValue = name,
}: OptionGroupProps) => (
  <MenuGroup dataTrackTag={dataTrackTag} dataTrackValue={dataTrackValue} label={label} isMulti={isMulti} name={name}>
    {children}
  </MenuGroup>
);

OptionGroup.id = MenuGroup.id;
OptionGroup.displayName = MenuGroup.id;

export default OptionGroup;
